"""Dependency-free CLI entry point for boolean parsing."""
import sys

_TRUE = {"true", "1", "yes"}
_FALSE = {"false", "0", "no"}


def parse(value: str) -> bool:
    """Parse a boolean value. Raises ValueError for unrecognized input."""
    v = value.strip().lower()
    if v in _TRUE:
        return True
    if v in _FALSE:
        return False
    raise ValueError(f"unrecognized boolean value: {value!r}")


def main(argv=None) -> int:
    """Entry point returning a deterministic exit code.

    0 – value parsed as true
    1 – value parsed as false
    2 – usage or parse error
    """
    if argv is None:
        argv = sys.argv[1:]

    if len(argv) != 1:
        print("usage: parser-cli <value>", file=sys.stderr)
        return 2

    try:
        result = parse(argv[0])
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2

    if result:
        print("true")
        return 0
    print("false")
    return 1


if __name__ == "__main__":
    sys.exit(main())
